/// `MobEffect.isInstantaneous()` 为真的效果。
pub static INSTANT_MOB_EFFECTS: &[&str] = &["minecraft:instant_damage", "minecraft:instant_health", "minecraft:saturation"];

/// 这个效果是不是瞬时的。
pub fn mob_effect_is_instantaneous(name: &str) -> bool { INSTANT_MOB_EFFECTS.binary_search(&name).is_ok() }

