/// 按名字查战利品表，名字要带命名空间。
pub fn loot_table(name: &str) -> Option<&'static str> { lookup(LOOT_TABLES, name) }

/// 按名字查战利品条件。
pub fn loot_predicate(name: &str) -> Option<&'static str> { lookup(LOOT_PREDICATES, name) }

/// 按名字查整数提供器。
pub fn context_int_provider(name: &str) -> Option<&'static str> { lookup(CONTEXT_INT_PROVIDERS, name) }

/// 按名字查浮点提供器。
pub fn context_float_provider(name: &str) -> Option<&'static str> { lookup(CONTEXT_FLOAT_PROVIDERS, name) }

/// 按名字查附魔定义。
pub fn enchantment(name: &str) -> Option<&'static str> { lookup(ENCHANTMENTS, name) }

/// 按名字查烧炼配方。
pub fn smelting_recipe(name: &str) -> Option<&'static str> { lookup(SMELTING_RECIPES, name) }

/// 按方块查掉落表。
pub fn block_loot_table(block: &str) -> Option<&'static str> { lookup(BLOCK_LOOT_TABLES, block) }

fn lookup(list: &'static [(&'static str, &'static str)], name: &str) -> Option<&'static str> {
    list.binary_search_by(|(key, _)| key.cmp(&name)).ok().map(|index| list[index].1)
}
